(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const W = 2800, H = 2100;
  const state = {
    started:false, paused:false, won:false, time:0, day:1, weather:0,
    player:{x:W/2,y:H/2+180,r:15,hp:100,stamina:100,hunger:100,dir:0,speed:210},
    cam:{x:0,y:0}, inventory:{wood:0,stone:0,fiber:0,berries:2,orbs:2}, xp:0, level:1,
    nodes:[], creatures:[], particles:[], camp:null, companion:null, selected:'bow',
    keys:{}, pointer:{x:0,y:0,down:false}, lastInteract:0, lastAttack:0, toastUntil:0,
    joystick:{active:false,x:0,y:0}, lastSave:0
  };
  const palettes = {
    grass:['#456744','#4b7048','#52764a','#496c43','#55794d'],
    trees:['#254832','#2c5538','#315b3c','#376142'], flowers:['#e9c879','#e6a3a0','#d3c9e8']
  };
  let dpr=1, vw=innerWidth, vh=innerHeight;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(min,max)=>min+Math.random()*(max-min);
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){
    vw=innerWidth; vh=innerHeight; dpr=Math.min(devicePixelRatio||1,2);
    canvas.width=Math.round(vw*dpr); canvas.height=Math.round(vh*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  addEventListener('resize',resize); resize();
  function makeWorld(){
    let seed=87341; const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
    for(let i=0;i<165;i++){
      const x=150+random()*(W-300),y=130+random()*(H-260);
      if(Math.hypot(x-W/2,y-(H/2+180))<150) continue;
      const roll=random();
      if(roll<.47) state.nodes.push({type:'tree',x,y,r:24+random()*15,hp:1,color:palettes.trees[Math.floor(random()*4)],variant:random()});
      else if(roll<.68) state.nodes.push({type:'rock',x,y,r:16+random()*9,hp:1,variant:random()});
      else if(roll<.85) state.nodes.push({type:'bush',x,y,r:15+random()*10,hp:1,variant:random()});
      else state.nodes.push({type:'flower',x,y,r:9+random()*7,hp:1,variant:random()});
    }
    state.creatures.push({kind:'mosskit',name:'Mosskit',x:W/2+275,y:H/2+150,hp:48,maxHp:48,r:19,dir:0,alert:false,roam:0,color:'#bedc80'});
    state.creatures.push({kind:'mosskit',name:'Mosskit',x:W/2-440,y:H/2-260,hp:48,maxHp:48,r:19,dir:1,alert:false,roam:0,color:'#bedc80'});
    state.creatures.push({kind:'bramble',name:'Brambleback',x:W/2+570,y:H/2-370,hp:75,maxHp:75,r:23,dir:2,alert:false,roam:0,color:'#d18c6d'});
    state.creatures.push({kind:'mosskit',name:'Mosskit',x:W/2-750,y:H/2+520,hp:48,maxHp:48,r:19,dir:0,alert:false,roam:0,color:'#bedc80'});
  }
  makeWorld();
  const toast=(message)=>{const el=$('toast');el.textContent=message;el.classList.add('show');state.toastUntil=performance.now()+2300;};
  function setObjective(title,text,count){$('objective-title').textContent=title;$('objective-text').textContent=text;$('objective-count').textContent=count;}
  function save(){
    try{localStorage.setItem('wildbound-save',JSON.stringify({p:{x:state.player.x,y:state.player.y,hp:state.player.hp,hunger:state.player.hunger},inv:state.inventory,xp:state.xp,day:state.day,camp:state.camp,companion:state.companion,won:state.won}));}catch(_e){}
  }
  function restore(){
    try{const s=JSON.parse(localStorage.getItem('wildbound-save'));if(!s)return;
      Object.assign(state.player,s.p||{});Object.assign(state.inventory,s.inv||{});state.xp=s.xp||0;state.day=s.day||1;state.camp=s.camp||null;state.companion=s.companion||null;state.won=!!s.won;
      if(state.camp)state.nodes=state.nodes.filter(n=>n.type!=='camp');
    }catch(_e){}
  }
  restore();
  function gainXP(amount){
    state.xp+=amount;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.player.hp=Math.min(100,state.player.hp+15);toast(`FIELD NOTES COMPLETE · WAYFARER LEVEL ${state.level}`);}
  }
  function nearbyTarget(max=88){
    let best=null,bd=max;
    for(const n of state.nodes){if(n.gone)continue;const d=dist(state.player,n)-n.r;if(d<bd){bd=d;best=n;}}
    for(const c of state.creatures){if(c.hp<=0)continue;const d=dist(state.player,c)-c.r;if(d<bd){bd=d;best=c;}}
    if(state.camp){const d=dist(state.player,state.camp)-40;if(d<bd){bd=d;best=state.camp;}}
    return best;
  }
  function interact(){
    const p=state.player, target=nearbyTarget(105);
    if(target&&target.type){
      if(target.type==='tree'){state.inventory.wood+=2;target.gone=true;gainXP(12);burst(target.x,target.y,'#c9a477',10);toast('Gathered 2 wood · the forest thanks you.');}
      else if(target.type==='rock'){state.inventory.stone+=2;target.gone=true;gainXP(12);burst(target.x,target.y,'#bdc9ba',9);toast('Gathered 2 stone.');}
      else if(target.type==='bush'){state.inventory.fiber+=2;state.inventory.berries+=1;target.gone=true;gainXP(10);burst(target.x,target.y,'#98c970',8);toast('Gathered fiber and a wild berry.');}
      else if(target.type==='flower'){state.inventory.fiber++;target.gone=true;gainXP(5);toast('Gathered a little soft fiber.');}
    } else if(target&&target.kind){
      if(target.kind==='bramble'){toast('A Brambleback is too wary to befriend.');return;}
      if(target.hp<target.maxHp*.55){tryCapture(target);}else toast(`${target.name} seems shy. Soften it with your bow first.`);
    } else if(target===state.camp){
      state.player.hp=Math.min(100,state.player.hp+35);state.player.hunger=Math.min(100,state.player.hunger+20);state.day++;toast('A safe night by the campfire. Day '+String(state.day).padStart(2,'0')+'.');save();
    } else if(!state.camp && state.inventory.wood>=5 && state.inventory.stone>=3){
      state.inventory.wood-=5;state.inventory.stone-=3;state.camp={x:p.x,y:p.y};gainXP(80);toast('Your little camp is ready. A home, at last.');
    } else if(!state.camp){toast('Gather 5 wood and 3 stone to make your first camp.');}
    else if(!state.companion){toast('Find a Mosskit, weaken it, then use an orb nearby.');}
    else if(!state.won){
      const shrine=shrinePos();
      if(dist(p,shrine)<130){winGame();}else toast('The old sunstone lies to the east. Follow the glow on your map.');
    }
    updateUI();
  }
  function shrinePos(){return{x:W-210,y:175};}
  function attack(){
    if(!state.started||state.paused||state.won)return;
    const now=performance.now();if(now-state.lastAttack<360)return;state.lastAttack=now;
    const p=state.player,target=state.creatures.filter(c=>c.hp>0).sort((a,b)=>dist(p,a)-dist(p,b))[0];
    if(!target||dist(p,target)>285){toast('No wildling in range. Wander closer.');return;}
    const damage=state.selected==='spear'?25:state.selected==='bow'?19:9;
    if(state.selected==='food'){eat();return;}
    target.hp=Math.max(0,target.hp-damage);target.alert=true;target.dir=Math.atan2(p.y-target.y,p.x-target.x);
    burst(target.x,target.y,target.color,5);if(target.hp===0){gainXP(25);toast(`${target.name} settled down. Try an orb while it is weak.`);}else toast(`${target.name} startled · ${Math.ceil(target.hp/target.maxHp*100)}% spirit`);
    updateUI();
  }
  function tryCapture(target){
    if(state.inventory.orbs<=0){toast('You are out of wilding orbs.');return;}
    if(target.kind==='bramble'){toast('This wildling is too fierce to befriend.');return;}
    state.inventory.orbs--;target.hp=0;state.companion={name:'Mosskit',level:1,icon:'✿',mood:'Curious'};gainXP(60);toast('Mosskit joined your journey!');updateUI();save();
    if(state.camp) setObjective('The sunstone calls','Visit the ancient sunstone in the eastern glade to complete your journey.','CAMP BUILT · COMPANION FOUND');
  }
  function useOrb(){const target=nearbyTarget(165);if(target&&target.kind){if(target.hp<target.maxHp*.55)tryCapture(target);else toast('Mosskit needs to trust you first. Weaken it with a few bow shots.');}else toast('Move close to a wildling before using an orb.');}
  function eat(){if(state.inventory.berries<=0){toast('No berries in your pack. Gather from green bushes.');return;}state.inventory.berries--;state.player.hunger=Math.min(100,state.player.hunger+38);state.player.hp=Math.min(100,state.player.hp+12);toast('Berry bun eaten · feeling much better.');updateUI();}
  function buildOrWin(){
    if(state.won)return;
    if(!state.camp){interact();return;}
    if(state.companion){if(dist(state.player,shrinePos())<130)winGame();else toast('Head to the ancient sunstone in the eastern glade.');return;}
    if(state.inventory.wood>=5&&state.inventory.stone>=3)interact();else toast('Gather wood and stone, then build your camp.');
  }
  function winGame(){state.won=true;save();openModal(`<div class="modal-head"><div><div class="modal-kicker">A WILDERNESS WORTH KNOWING</div><h2>The Reach is yours</h2></div><button class="close-modal" data-close>×</button></div><p class="modal-copy">You made a home beneath the mosslight, earned a wildling’s trust, and followed the old sunstone’s glow. The wild is no longer a place you pass through — it’s a place you belong.</p><div class="ending-stats"><span>DAY <b>${String(state.day).padStart(2,'0')}</b></span><span>WAYFARER <b>LV ${String(state.level).padStart(2,'0')}</b></span><span>FIELD NOTES <b>${state.level*100+state.xp} XP</b></span></div><div class="modal-actions"><button class="primary-action" data-close>KEEP EXPLORING <span>→</span></button><button class="secondary-action" id="reset-game">START A NEW JOURNEY</button></div>`);}
  function openModal(html){$('modal-content').innerHTML=html;$('modal-backdrop').classList.remove('hidden');}
  function closeModal(){$('modal-backdrop').classList.add('hidden');}
  function showMap(){openModal(`<div class="modal-head"><div><div class="modal-kicker">FIELD JOURNAL · SURVEY 01</div><h2>The Verdant Reach</h2></div><button class="close-modal" data-close>×</button></div><div class="large-map"><canvas id="big-map" width="720" height="470"></canvas></div><p class="modal-copy">You are the pale green spark. The gold marker is the ancient sunstone, east across the forest. Gather, befriend a Mosskit, and make the Reach your home.</p><div class="map-legend"><span>✦ YOU</span><span>⌂ CAMP</span><span>✧ SUNSTONE</span><span>● WILDLING</span></div>`);drawBigMap();}
  function drawBigMap(){const c=$('big-map');if(!c)return;const g=c.getContext('2d');g.fillStyle='#34583c';g.fillRect(0,0,c.width,c.height);for(let i=0;i<260;i++){const x=(i*173)%c.width,y=(i*97)%c.height;g.fillStyle=i%3?'#466b48':'#52764b';g.beginPath();g.arc(x,y,5+(i%9),0,Math.PI*2);g.fill();}g.fillStyle='#5e986c';g.beginPath();g.ellipse(c.width*.38,c.height*.54,75,38,-.3,0,Math.PI*2);g.fill();const px=state.player.x/W*c.width,py=state.player.y/H*c.height;g.fillStyle='#d5f17e';g.beginPath();g.arc(px,py,8,0,7);g.fill();for(const cr of state.creatures.filter(c=>c.hp>0)){g.fillStyle=cr.kind==='bramble'?'#d18c6d':'#d7e7a0';g.beginPath();g.arc(cr.x/W*c.width,cr.y/H*c.height,5,0,7);g.fill();}if(state.camp){g.fillStyle='#e7c879';g.fillRect(state.camp.x/W*c.width-5,state.camp.y/H*c.height-5,10,10);}g.fillStyle='#ffe29a';g.font='20px sans-serif';g.fillText('✧',shrinePos().x/W*c.width-9,shrinePos().y/H*c.height+7);}
  function modalClick(e){const btn=e.target.closest('[data-close]');if(btn){closeModal();return;}if(e.target.id==='reset-game'){localStorage.removeItem('wildbound-save');location.reload();}}
  $('modal-content').addEventListener('click',modalClick);$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal();});
  $('begin-button').addEventListener('click',()=>{state.started=true;$('start-overlay').classList.add('dismissed');toast('A quiet forest awaits. Walk with WASD or the arrow keys.');});
  $('capture-button').addEventListener('click',useOrb);$('map-btn').addEventListener('click',showMap);
  $('pause-btn').addEventListener('click',()=>{state.paused=!state.paused; if(state.paused)openModal(`<div class="modal-head"><div><div class="modal-kicker">TAKE A BREATH</div><h2>Journey paused</h2></div><button class="close-modal" data-close>×</button></div><p class="modal-copy">Your progress is saved as you explore. The Reach will be here when you’re ready.</p><div class="modal-actions"><button class="primary-action" data-close id="resume-game">BACK TO THE REACH <span>→</span></button><button class="secondary-action" id="pause-map">VIEW FIELD MAP</button></div>`);else closeModal();});
  $('modal-content').addEventListener('click',e=>{if(e.target.id==='resume-game'){state.paused=false;closeModal();}if(e.target.id==='pause-map')showMap();});
  document.querySelectorAll('.hotbar-slot').forEach(b=>b.addEventListener('click',()=>selectItem(b.dataset.slot)));
  function selectItem(item){state.selected=item;document.querySelectorAll('.hotbar-slot').forEach(b=>b.classList.toggle('active',b.dataset.slot===item));if(item==='orb')toast('Wilding orb ready · use Q near a weakened wildling.');if(item==='food')toast('Berry bun ready · press 4 or click to eat.');}
  $('touch-interact').addEventListener('click',interact);$('touch-attack').addEventListener('click',attack);$('touch-capture').addEventListener('click',useOrb);
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const k=e.key.toLowerCase();state.keys[k]=true;if(e.repeat)return;if(k==='e')interact();if(k==='q')useOrb();if(k===' '||k==='f')attack();if(k==='m')showMap();if(k==='escape'){if(!$('modal-backdrop').classList.contains('hidden')){closeModal();state.paused=false;}else $('pause-btn').click();}if(k==='1')selectItem('bow');if(k==='2')selectItem('spear');if(k==='3')selectItem('orb');if(k==='4'){selectItem('food');eat();}});
  addEventListener('keyup',e=>state.keys[e.key.toLowerCase()]=false);
  canvas.addEventListener('pointermove',e=>{state.pointer.x=e.clientX;state.pointer.y=e.clientY;});canvas.addEventListener('pointerdown',e=>{if(!state.started)return;state.pointer.down=true;attack();});addEventListener('pointerup',()=>state.pointer.down=false);
  const joy=$('joystick'),knob=$('joy-knob');
  joy.addEventListener('pointerdown',e=>{state.joystick.active=true;joy.setPointerCapture(e.pointerId);moveJoy(e);});joy.addEventListener('pointermove',e=>{if(state.joystick.active)moveJoy(e);});joy.addEventListener('pointerup',()=>{state.joystick.active=false;state.joystick.x=state.joystick.y=0;knob.style.transform='translate(0,0)';});
  function moveJoy(e){const r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),mag=Math.min(1,len/43);state.joystick.x=len?dx/len*mag:0;state.joystick.y=len?dy/len*mag:0;knob.style.transform=`translate(${state.joystick.x*34}px,${state.joystick.y*34}px)`;}
  function burst(x,y,color,n){for(let i=0;i<n;i++)state.particles.push({x,y,vx:rand(-90,90),vy:rand(-130,50),life:rand(.35,.8),max:.8,color});}
  function update(dt){
    state.time+=dt;if(!state.started||state.paused)return;
    const p=state.player;let mx=(state.keys.d||state.keys.arrowright?1:0)-(state.keys.a||state.keys.arrowleft?1:0)+state.joystick.x;let my=(state.keys.s||state.keys.arrowdown?1:0)-(state.keys.w||state.keys.arrowup?1:0)+state.joystick.y;const mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag;}
    const running=state.keys.shift&&p.stamina>2;const speed=p.speed*(running?1.55:1);if(mag>.05){p.x=clamp(p.x+mx*speed*dt,35,W-35);p.y=clamp(p.y+my*speed*dt,35,H-35);p.dir=Math.atan2(my,mx);}
    p.stamina=clamp(p.stamina+(running&&mag>.1?-28:18)*dt,0,100);p.hunger=clamp(p.hunger-.22*dt,0,100);if(p.hunger<=0)p.hp=clamp(p.hp-1.6*dt,1,100);
    if(state.companion){const c=state.companion;c.x??=p.x-38;c.y??=p.y+20;const d=Math.hypot(c.x-p.x,c.y-p.y);if(d>55){c.x+=(p.x-34-c.x)*Math.min(1,dt*2);c.y+=(p.y+18-c.y)*Math.min(1,dt*2);}}
    for(const c of state.creatures){if(c.hp<=0)continue;c.roam-=dt;if(c.alert&&c.kind==='bramble'&&dist(c,p)<340){c.dir=Math.atan2(p.y-c.y,p.x-c.x);c.x+=Math.cos(c.dir)*65*dt;c.y+=Math.sin(c.dir)*65*dt;if(dist(c,p)<c.r+p.r+4&&state.time-c.lastHit>1.3){p.hp=Math.max(1,p.hp-8);c.lastHit=state.time;toast('Brambleback struck! Keep your distance.');}}else if(c.roam<=0){c.dir=rand(0,Math.PI*2);c.roam=rand(1.2,4);}else if(!c.alert){c.x+=Math.cos(c.dir)*12*dt;c.y+=Math.sin(c.dir)*12*dt;}}
    for(const pt of state.particles){pt.x+=pt.vx*dt;pt.y+=pt.vy*dt;pt.vy+=150*dt;pt.life-=dt;}state.particles=state.particles.filter(pt=>pt.life>0);
    state.cam.x=clamp(p.x-vw/2,0,W-vw);state.cam.y=clamp(p.y-vh/2,0,H-vh);
    const near=nearbyTarget(90);const hint=$('world-hint');if(near){hint.classList.add('visible');hint.querySelector('span:last-child').textContent=near.kind?(near.hp<near.maxHp*.55?'Use an orb to befriend':'A wildling · click to attack'):near.type?`Gather ${near.type}`:'Rest at your camp';}else hint.classList.remove('visible');
    if(performance.now()-state.lastSave>12000){save();state.lastSave=performance.now();}updateUI();
  }
  function updateUI(){
    const p=state.player, inv=state.inventory;
    for(const [name,val] of [['health',p.hp],['stamina',p.stamina],['hunger',p.hunger]]){$(`${name}-fill`).style.width=val+'%';$(`${name}-value`).textContent=Math.round(val);}
    $('wood-count').textContent=inv.wood;$('stone-count').textContent=inv.stone;$('fiber-count').textContent=inv.fiber;
    $('orb-count').textContent=`${inv.orbs} BASIC ORB${inv.orbs===1?'':'S'}`;$('level').textContent=String(state.level).padStart(2,'0');$('xp-value').textContent=`${state.xp} / ${state.level*100} XP`;$('xp-fill').style.width=(state.xp/(state.level*100)*100)+'%';$('day-count').textContent=String(state.day).padStart(2,'0');
    $('crew-count').textContent=state.companion?'1 / 1':'0 / 1';$('empty-companion').classList.toggle('hidden',!!state.companion);$('companion-card').classList.toggle('hidden',!state.companion);
    if(state.companion)$('companion-card').innerHTML='<div class="companion-main"><div class="companion-portrait">✿</div><div><b>Mosskit</b><small>LV 01 · CURIOUS</small></div></div><div class="companion-bars"><i style="width:84%"></i></div>';
    const count=`WOOD ${inv.wood}/5 · STONE ${inv.stone}/3`;
    if(!state.camp)setObjective('A place to call home','Gather wood and stone, then build your first little camp.',count);
    else if(!state.companion)setObjective('A friend in the wild','Find a Mosskit, gently weaken it, and use a wilding orb nearby.',`CAMP BUILT · ORBS ${inv.orbs}`);
    else if(!state.won)setObjective('The sunstone calls','Visit the ancient sunstone in the eastern glade to complete your journey.','CAMP BUILT · COMPANION FOUND');
    $('coordinates').textContent=`N ${String(Math.round((H-p.y)/100)).padStart(2,'0')} · E ${String(Math.round(p.x/100)).padStart(2,'0')}`;
  }
  function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}

  function drawWorld(){
    const cam=state.cam,p=state.player;
    ctx.clearRect(0,0,vw,vh);ctx.fillStyle='#426542';ctx.fillRect(0,0,vw,vh);
    ctx.save();ctx.translate(-cam.x,-cam.y);
    const startX=Math.floor(cam.x/100)*100,startY=Math.floor(cam.y/100)*100;
    for(let y=startY;y<cam.y+vh+100;y+=100)for(let x=startX;x<cam.x+vw+100;x+=100){
      const n=(Math.sin(x*12.23+y*2.7)*43758.5)%1;ctx.fillStyle=palettes.grass[Math.abs(Math.floor(n*4))%5];ctx.fillRect(x,y,102,102);
      for(let j=0;j<5;j++){const fx=x+((j*37+Math.abs(n*100)|0)%93),fy=y+((j*61+Math.abs(n*79)|0)%93);ctx.fillStyle=j%3===0?'#9bad6840':'#b0c47924';ctx.beginPath();ctx.ellipse(fx,fy,2,1.3,-.4,0,Math.PI*2);ctx.fill();}
    }
    // A soft creek and the winding trail make the clearing easy to read.
    ctx.save();ctx.strokeStyle='#6f9877';ctx.lineWidth=90;ctx.globalAlpha=.6;ctx.beginPath();ctx.moveTo(-100,1500);ctx.bezierCurveTo(650,1200,820,1780,1430,1430);ctx.bezierCurveTo(1900,1160,2100,1430,3000,890);ctx.stroke();ctx.restore();
    ctx.save();ctx.strokeStyle='#b9aa78';ctx.lineWidth=42;ctx.lineCap='round';ctx.globalAlpha=.58;ctx.beginPath();ctx.moveTo(80,1800);ctx.bezierCurveTo(680,1650,730,1090,1330,1170);ctx.bezierCurveTo(1910,1250,1970,670,2720,280);ctx.stroke();ctx.restore();
    // The old pond west of the starting grove.
    ctx.save();ctx.fillStyle='#4b887c';ctx.globalAlpha=.85;ctx.beginPath();ctx.ellipse(910,560,178,98,-.32,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#9ab98d';ctx.lineWidth=7;ctx.stroke();ctx.globalAlpha=.24;ctx.strokeStyle='#c9dfbb';ctx.lineWidth=2;for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(900,558,40+i*24,15+i*11,-.32,0,Math.PI*2);ctx.stroke();}ctx.restore();
    for(const n of state.nodes){if(n.gone)continue;if(n.x<cam.x-80||n.x>cam.x+vw+80||n.y<cam.y-100||n.y>cam.y+vh+80)continue;drawNode(n);}
    drawShrine();if(state.camp)drawCamp(state.camp);
    for(const c of state.creatures){if(c.hp<=0)continue;drawCreature(c);}
    if(state.companion)drawCompanion();drawPlayer();
    for(const pt of state.particles){ctx.globalAlpha=clamp(pt.life/pt.max,0,1);ctx.fillStyle=pt.color;ctx.beginPath();ctx.arc(pt.x,pt.y,3.5,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    ctx.restore();drawMiniMap();
    // Gentle atmospheric wash.
    const night=(Math.sin(state.time*.045)+1)/2;ctx.fillStyle=`rgba(11,25,26,${.04+night*.1})`;ctx.fillRect(0,0,vw,vh);
  }
  function drawNode(n){
    ctx.save();ctx.translate(n.x,n.y);
    ctx.fillStyle='#1b33294c';ctx.beginPath();ctx.ellipse(0,8,n.r*1.35,n.r*.5,0,0,Math.PI*2);ctx.fill();
    if(n.type==='tree'){
      ctx.fillStyle='#79563a';ctx.fillRect(-6,-9,12,24);ctx.fillStyle=n.color;ctx.beginPath();ctx.arc(-4,-22,n.r*.75,0,7);ctx.arc(11,-28,n.r*.66,0,7);ctx.arc(1,-43,n.r*.76,0,7);ctx.fill();ctx.fillStyle='#71905a55';ctx.beginPath();ctx.arc(-6,-48,n.r*.42,0,7);ctx.fill();
      ctx.fillStyle='#d5e0a0';ctx.globalAlpha=.68;ctx.beginPath();ctx.arc(2,-42,2,0,7);ctx.fill();
    }else if(n.type==='rock'){
      ctx.fillStyle='#9aa99a';ctx.beginPath();ctx.moveTo(-n.r,-3);ctx.lineTo(-n.r*.65,-n.r*.65);ctx.lineTo(1,-n.r);ctx.lineTo(n.r*.78,-n.r*.5);ctx.lineTo(n.r,4);ctx.lineTo(n.r*.43,9);ctx.lineTo(-n.r*.7,8);ctx.closePath();ctx.fill();ctx.fillStyle='#d3d5bb';ctx.beginPath();ctx.moveTo(-n.r*.6,-n.r*.48);ctx.lineTo(1,-n.r*.87);ctx.lineTo(n.r*.53,-n.r*.42);ctx.lineTo(-1,-n.r*.25);ctx.fill();
    }else if(n.type==='bush'){
      ctx.fillStyle='#3b7149';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(-n.r*.6+i*n.r*.29,-3+(i%2)*-5,n.r*.48,0,7);ctx.fill();}ctx.fillStyle='#d86565';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(-n.r*.35+i*n.r*.36,-n.r*.25,2.4,0,7);ctx.fill();}
    }else{
      ctx.strokeStyle='#779b61';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,2);ctx.lineTo(0,-n.r);ctx.stroke();ctx.fillStyle=palettes.flowers[Math.floor(n.variant*3)];for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(Math.cos(i*1.25)*4,-n.r+Math.sin(i*1.25)*4,3.2,0,7);ctx.fill();}ctx.fillStyle='#e7d47b';ctx.beginPath();ctx.arc(0,-n.r,2,0,7);ctx.fill();
    }
    ctx.restore();
  }
  function drawCreature(c){
    ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.dir*.08);
    ctx.fillStyle='#192e274a';ctx.beginPath();ctx.ellipse(0,8,c.r*1.3,c.r*.55,0,0,7);ctx.fill();
    if(c.kind==='mosskit'){
      ctx.fillStyle='#a8c97b';ctx.beginPath();ctx.ellipse(0,-3,19,15,0,0,7);ctx.fill();ctx.fillStyle='#c8df94';ctx.beginPath();ctx.arc(0,-12,12,0,7);ctx.fill();ctx.fillStyle='#7fa164';ctx.beginPath();ctx.moveTo(-8,-19);ctx.lineTo(-13,-31);ctx.lineTo(-2,-24);ctx.fill();ctx.beginPath();ctx.moveTo(7,-20);ctx.lineTo(13,-30);ctx.lineTo(12,-17);ctx.fill();ctx.fillStyle='#263a2b';ctx.beginPath();ctx.arc(-4,-12,1.6,0,7);ctx.arc(4,-12,1.6,0,7);ctx.fill();ctx.fillStyle='#dce9b2';ctx.beginPath();ctx.arc(-7,-22,4,0,7);ctx.arc(5,-23,3,0,7);ctx.fill();
    }else{
      ctx.fillStyle='#7e6653';ctx.beginPath();ctx.ellipse(0,-3,24,17,0,0,7);ctx.fill();ctx.fillStyle='#ca9570';ctx.beginPath();ctx.ellipse(0,-15,14,12,0,0,7);ctx.fill();ctx.fillStyle='#54423c';ctx.beginPath();ctx.moveTo(-11,-21);ctx.lineTo(-18,-35);ctx.lineTo(-4,-26);ctx.fill();ctx.moveTo(10,-21);ctx.lineTo(18,-34);ctx.lineTo(5,-24);ctx.fill();ctx.fillStyle='#f0d7a4';ctx.beginPath();ctx.arc(-5,-16,2,0,7);ctx.arc(5,-16,2,0,7);ctx.fill();
    }
    if(c.hp<c.maxHp){ctx.fillStyle='#1a2c25';ctx.fillRect(-21,-43,42,4);ctx.fillStyle='#e8ca76';ctx.fillRect(-21,-43,42*c.hp/c.maxHp,4);}
    if(dist(c,state.player)<210){ctx.font='10px DM Sans,sans-serif';ctx.textAlign='center';ctx.fillStyle='#f2f2dc';ctx.fillText(c.name,0,-49);}
    ctx.restore();
  }
  function drawPlayer(){
    const p=state.player;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#162b2458';ctx.beginPath();ctx.ellipse(0,9,17,8,0,0,7);ctx.fill();ctx.rotate(p.dir);
    ctx.fillStyle='#314d3c';ctx.beginPath();ctx.ellipse(0,-3,12,15,0,0,7);ctx.fill();ctx.fillStyle='#d9bd8f';ctx.beginPath();ctx.arc(0,-17,9,0,7);ctx.fill();ctx.fillStyle='#a26e4d';ctx.beginPath();ctx.arc(0,-21,10,Math.PI,0);ctx.fill();ctx.fillStyle='#d2e88c';ctx.fillRect(8,-7,8,2);ctx.restore();
  }
  function drawCompanion(){const c=state.companion;ctx.save();ctx.translate(c.x,c.y);ctx.fillStyle='#9eba70';ctx.beginPath();ctx.ellipse(0,-3,12,9,0,0,7);ctx.fill();ctx.fillStyle='#c9de91';ctx.beginPath();ctx.arc(0,-11,8,0,7);ctx.fill();ctx.fillStyle='#31412b';ctx.beginPath();ctx.arc(-3,-12,1,0,7);ctx.arc(3,-12,1,0,7);ctx.fill();ctx.restore();}
  function drawCamp(c){ctx.save();ctx.translate(c.x,c.y);ctx.fillStyle='#392d24';ctx.beginPath();ctx.ellipse(0,8,41,20,0,0,7);ctx.fill();ctx.fillStyle='#94714c';ctx.beginPath();ctx.moveTo(-24,4);ctx.lineTo(0,-28);ctx.lineTo(25,4);ctx.closePath();ctx.fill();ctx.fillStyle='#d2aa70';ctx.beginPath();ctx.moveTo(-15,3);ctx.lineTo(0,-20);ctx.lineTo(15,3);ctx.closePath();ctx.fill();ctx.fillStyle='#ffc971';ctx.beginPath();ctx.arc(0,7,9,0,7);ctx.fill();ctx.fillStyle='#fff0b0';ctx.beginPath();ctx.arc(0,6,4,0,7);ctx.fill();ctx.restore();}
  function drawShrine(){const s=shrinePos();ctx.save();ctx.translate(s.x,s.y);const glow=ctx.createRadialGradient(0,-18,4,0,-18,85);glow.addColorStop(0,'#ffe9a099');glow.addColorStop(1,'#ffe9a000');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,-18,85,0,7);ctx.fill();ctx.fillStyle='#857d61';ctx.beginPath();ctx.moveTo(-36,8);ctx.lineTo(-29,-28);ctx.lineTo(-10,-40);ctx.lineTo(-2,-8);ctx.lineTo(10,-47);ctx.lineTo(33,-28);ctx.lineTo(38,8);ctx.closePath();ctx.fill();ctx.fillStyle='#dac47d';ctx.beginPath();ctx.moveTo(-13,-8);ctx.lineTo(0,-34);ctx.lineTo(15,-7);ctx.lineTo(0,2);ctx.closePath();ctx.fill();ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff0b5';ctx.fillText('ANCIENT SUNSTONE',0,-55);ctx.restore();}
  function drawMiniMap(){
    const w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#3e6544';mctx.fillRect(0,0,w,h);
    for(let i=0;i<80;i++){mctx.fillStyle=i%3?'#4c7049':'#57784c';mctx.beginPath();mctx.arc((i*71)%w,(i*43)%h,3+(i%5),0,7);mctx.fill();}
    mctx.fillStyle='#4b887c';mctx.beginPath();mctx.ellipse(w*.32,h*.27,18,9,-.3,0,7);mctx.fill();
    for(const c of state.creatures){if(c.hp<=0)continue;mctx.fillStyle=c.kind==='bramble'?'#d18c6d':'#d7e7a0';mctx.beginPath();mctx.arc(c.x/W*w,c.y/H*h,2.3,0,7);mctx.fill();}
    if(state.camp){mctx.fillStyle='#e7c879';mctx.fillRect(state.camp.x/W*w-2,state.camp.y/H*h-2,5,5);}
    const sp=shrinePos();mctx.fillStyle='#ffe29a';mctx.beginPath();mctx.arc(sp.x/W*w,sp.y/H*h,3,0,7);mctx.fill();
    const x=state.player.x/W*w,y=state.player.y/H*h;mctx.fillStyle='#d5f17e';mctx.beginPath();mctx.arc(x,y,4.5,0,7);mctx.fill();mctx.strokeStyle='#f5ffd5';mctx.lineWidth=1.5;mctx.stroke();
  }
  function frame(now){const dt=Math.min(.04,(now-(frame.last||now))/1000);frame.last=now;update(dt);drawWorld();if(now>state.toastUntil)$('toast').classList.remove('show');requestAnimationFrame(frame);}
  updateUI();requestAnimationFrame(frame);
})();

