onospace;opacity:0;pointer-events:none;transition:all .22s;z-index:8}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none}.modal-backdrop{position:absolute;inset:0;background:#081411b9;backdrop-filter:blur(5px);z-index:6;display:grid;place-items:center;padding:20px}.modal-backdrop.hidden{display:none}.modal{width:min(520px,96vw);max-height:88dvh;overfl
