(() => {
  'use strict';
  const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d'),$=id=>document.getElementById(id);
  const W=2800,H=2100,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const state={started:false,paused:false,won:false,time:0,day:1,player:{x:W/2,y:H/2+180,r:15,hp:100,stamina:100,hunger:100,dir:0,speed:210},cam:{x:0,y:0},inventory:{wood:0,stone:0,fiber:0,berries:2,orbs:2},xp:0,level:1,nodes:[],creatures:[],particles:[],camp:null,companion:null,selected:'bow',keys:{},pointer:{},joystick:{active:false,x:0,y:0},lastAttack:0,lastSave:0,toastUntil:0};
  const palettes={grass:['#456744','#4b7048','#52764a','#496c43','#55794d'],trees:['#254832','#2c5538','#315b3c','#376142'],flowers:['#e9c879','#e6a3a0','#d3c9e8']};
  let dpr=1,vw=innerWidth,vh=innerHeight;
  function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(vw*dpr);canvas.height=Math.round(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}addEventListener('resize',resize);resize();
  function makeWorld(){let seed=87341;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<165;i++){const x=150+random()*(W-300),y=130+random()*(H-260);if(Math.hypot(x-W/2,y-(H/2+180))<150)continue;const r=random();if(r<.47)state.nodes.push({type:'tree',x,y,r:24+random()*15,hp:1,color:palettes.trees[Math.floor(random()*4)],variant:random()});else if(r<.68)state.nodes.push({type:'rock',x,y,r:16+random()*9,hp:1,variant:random()});else if(r<.85)state.nodes.push({type:'bush',x,y,r:15+random()*10,hp:1,variant:random()});else state.nodes.push({type:'flower',x,y,r:9+random()*7,hp:1,variant:random()});}state.creatures.push({kind:'mosskit',name:'Mosskit',x:W/2+275,y:H/2+150,hp:48,maxHp:48,r:19,dir:0,alert:false,roam:0,color:'#bedc80'},{kind:'mosskit',name:'Mosskit',x:W/2-440,y:H/2-260,hp:48,maxHp:48,r:19,dir:1,alert:false,roam:0,color:'#bedc80'},{kind:'bramble',name:'Brambleback',x:W/2+570,y:H/2-370,hp:75,maxHp:75,r:23,dir:2,alert:false,roam:0,color:'#d18c6d'},{kind:'mosskit',name:'Mosskit',x:W/2-750,y:H/2+520,hp:48,maxHp:48,r:19,dir:0,alert:false,roam:0,color:'#bedc80'});}
  makeWorld();
  const toast=message=>{const el=$('toast');el.textContent=message;el.classList.add('show');state.toastUntil=performance.now()+2300;};
  function setObjective(title,text,count){$('objective-title').textContent=title;$('objective-text').textContent=text;$('objective-count').textContent=count;}
  function save(){try{localStorage.setItem('wildbound-save',JSON.stringify({p:{x:state.player.x,y:state.player.y,hp:state.player.hp,hunger:state.player.hunger},inv:state.inventory,xp:state.xp,day:state.day,camp:state.camp,companion:state.companion,won:state.won}));}catch(_e){}}
  function restore(){try{const s=JSON.parse(localStorage.getItem('wildbound-save'));if(!s)return;Object.assign(state.player,s.p||{});Object.assign(state.inventory,s.inv||{});state.xp=s.xp||0;state.day=s.day||1;state.camp=s.camp||null;state.companion=s.companion||null;state.won=!!s.won;}catch(_e){}}restore();
  function gainXP(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.player.hp=Math.min(100,state.player.hp+15);toast(`FIELD NOTES COMPLETE · WAYFARER LEVEL ${state.level}`);}}
  function nearbyTarget(max=88){let best=null,bd=max;for(const n of state.nodes){if(n.gone)continue;const d=dist(state.player,n)-n.r;if(d<bd){bd=d;best=n;}}for(const c of state.creatures){if(c.hp<=0)continue;const d=dist(state.player,c)-c.r;if(d<bd){bd=d;best=c;}}if(state.camp){const d=dist(state.player,state.camp)-40;if(d<bd){bd=d;best=state.camp;}}return best;}
  function burst(x,y,color,n){for(let i=0;i<n;i++)state.particles.push({x,y,vx:rand(-90,90),vy:rand(-130,50),life:rand(.35,.8),max:.8,color});}
  function interact(){const p=state.player,t=nearbyTarget(105);if(t&&t.type){if(t.type==='tree'){state.inventory.wood+=2;t.gone=true;gainXP(12);burst(t.x,t.y,'#c9a477',10);toast('Gathered 2 wood · the forest thanks you.');}else if(t.type==='rock'){state.inventory.stone+=2;t.gone=true;gainXP(12);burst(t.x,t.y,'#bdc9ba',9);toast('Gathered 2 stone.');}else if(t.type==='bush'){state.inventory.fiber+=2;state.inventory.berries++;t.gone=true;gainXP(10);burst(t.x,t.y,'#98c970',8);toast('Gathered fiber and a wild berry.');}else{state.inventory.fiber++;t.gone=true;gainXP(5);toast('Gathered a little soft fiber.');}}else if(t&&t.kind){if(t.kind==='bramble')toast('A Brambleback is too wary to befriend.');else if(t.hp<t.maxHp*.55)tryCapture(t);else toast(`${t.name} seems shy. Soften it with your bow first.`);}else if(t===state.camp){p.hp=Math.min(100,p.hp+35);p.hunger=Math.min(100,p.hunger+20);state.day++;toast('A safe night by the campfire. Day '+String(state.day).padStart(2,'0')+'.');save();}else if(!state.camp&&state.inventory.wood>=5&&state.inventory.stone>=3){state.inventory.wood-=5;state.inventory.stone-=3;state.camp={x:p.x,y:p.y};gainXP(80);toast('Your little camp is ready. A home, at last.');}else if(!state.camp)toast('Gather 5 wood and 3 stone to make your first camp.');else if(!state.companion)toast('Find a Mosskit, weaken it, then use an orb nearby.');else if(dist(p,shrinePos())<130)winGame();else toast('The old sunstone lies to the east. Follow the glow on your map.');updateUI();}
  function shrinePos(){return{x:W-210,y:175};}
  function attack(){if(!state.started||state.paused||state.won)return;const now=performance.now();if(now-state.lastAttack<360)return;state.lastAttack=now;const p=state.player,t=state.creatures.filter(c=>c.hp>0).sort((a,b)=>dist(p,a)-dist(p,b))[0];if(!t||dist(p,t)>285){toast('No wildling in range. Wander closer.');return;}if(state.selected==='food'){eat();return;}const damage=state.selected==='spear'?25:state.selected==='bow'?19:9;t.hp=t.kind==='mosskit'?Math.max(1,t.hp-damage):Math.max(0,t.hp-damage);t.alert=true;t.dir=Math.atan2(p.y-t.y,p.x-t.x);burst(t.x,t.y,t.color,5);if(t.hp===1&&t.kind==='mosskit'){gainXP(25);toast(`${t.name} is calm now · use an orb nearby.`);}else if(t.hp===0){gainXP(25);toast(`${t.name} scampered off into the woods.`);}else toast(`${t.name} startled · ${Math.ceil(t.hp/t.maxHp*100)}% spirit`);updateUI();}
  function tryCapture(t){if(state.inventory.orbs<=0){toast('You are out of wilding orbs.');return;}if(t.kind==='bramble'){toast('This wildling is too fierce to befriend.');return;}state.inventory.orbs--;t.hp=0;state.companion={name:'Mosskit',level:1,icon:'✿',mood:'Curious'};gainXP(60);toast('Mosskit joined your journey!');updateUI();save();}
  function useOrb(){const t=nearbyTarget(165);if(t&&t.kind){if(t.hp<t.maxHp*.55)tryCapture(t);else toast('Mosskit needs to trust you first. Weaken it with a few bow shots.');}else toast('Move close to a wildling before using an orb.');}
  function eat(){if(state.inventory.berries<=0){toast('No berries in your pack. Gather from green bushes.');return;}state.inventory.berries--;state.player.hunger=Math.min(100,state.player.hunger+38);state.player.hp=Math.min(100,state.player.hp+12);toast('Berry bun eaten · feeling much better.');updateUI();}
